func TestShipcheckLocalJSONSuccessWithoutMCP(t *testing.T) {
	stdout, stderr, err := runCLIForDocsTest(t, "shipcheck", "local", "--json")
	if err != nil {
		t.Fatalf("shipcheck local --json returned error: %v", err)
	}
	if stderr != "" {
		t.Fatalf("shipcheck local wrote stderr: %q", stderr)
	}

	var got shipcheckLocalResponse
	if err := json.Unmarshal([]byte(stdout), &got); err != nil {
		t.Fatalf("shipcheck local --json emitted invalid JSON: %v\n%s", err, stdout)
	}
	if got.Command != "shipcheck local" || !got.Passed {
		t.Fatalf("wrong shipcheck response: %#v", got)
	}
	if len(got.Checks) < 4 {
		t.Fatalf("shipcheck should report concrete checks, got %#v", got.Checks)
	}
	if !got.Safety.LocalOnly || !got.Safety.CredentialFree || !got.Safety.NoAPICalls || !got.Safety.NoDocsEndpointCalls || !got.Safety.NoProductionWrites {
		t.Fatalf("shipcheck safety should prove local credential-free execution: %#v", got.Safety)
	}
	if got.Safety.ChildProcessExecuted || got.Safety.ChildEnvAllowlisted || got.Safety.ChildProcessSandboxed {
		t.Fatalf("shipcheck without --mcp-binary should not claim child-process proof: %#v", got.Safety)
	}
	if got.Safety.CallsGitHub || got.Safety.CallsNPM || got.Safety.CallsHomebrew || got.Safety.Publishes || got.Safety.Signs || got.Safety.Notarizes || got.Safety.ReadsSecrets {
		t.Fatalf("shipcheck safety should reject external release or secret surfaces: %#v", got.Safety)
	}
	if strings.Contains(strings.ToLower(stdout), "bearer ") || strings.Contains(stdout, "STRADDLE_TOKEN=") || strings.Contains(stdout, "sk_live") || strings.Contains(stdout, "sk_test") {
		t.Fatalf("shipcheck local should not emit token literals:\n%s", stdout)
	}
}

