func TestShipcheckLocalFakeMCPMissingRequiredToolFails(t *testing.T) {
	tools := []string{}
	for _, name := range requiredShipcheckMCPTools() {
		if name != "release_plan" {
			tools = append(tools, name)
		}
	}
	binary := writeFakeMCPBinary(t, tools)

	stdout, _, err := runCLIForDocsTest(t, "shipcheck", "local", "--mcp-binary", binary, "--json")
	if err == nil {
		t.Fatalf("shipcheck local should fail when MCP tool is missing")
	}
	if !strings.Contains(err.Error(), "release_plan") {
		t.Fatalf("error should mention missing release_plan, got %v", err)
	}
	var got shipcheckLocalResponse
	if unmarshalErr := json.Unmarshal([]byte(stdout), &got); unmarshalErr != nil {
		t.Fatalf("failed shipcheck should still emit JSON: %v\n%s", unmarshalErr, stdout)
	}
	if got.Passed {
		t.Fatalf("shipcheck should not pass with missing MCP tool: %#v", got)
	}
	check := shipcheckCheckByName(t, got.Checks, "mcp_tools")
	if check.Passed || !strings.Contains(check.Note, "release_plan") {
		t.Fatalf("mcp_tools should record missing release_plan: %#v", check)
	}
}

func TestShipcheckLocalRejectsDeliverBeforeDelivery(t *testing.T) {
	target := filepath.Join(t.TempDir(), "shipcheck-delivery.json")
	home := t.TempDir()
	t.Setenv("HOME", home)

	oldArgs := os.Args
	t.Cleanup(func() {
		os.Args = oldArgs
	})
	os.Args = []string{
		"straddle-pp-cli",
		"shipcheck",
		"local",
		"--deliver",
		"file:" + target,
		"--profile",
		"missing-profile",
	}

	err := Execute()
	if err == nil {
		t.Fatalf("shipcheck local should reject --deliver")
	}
	if !strings.Contains(err.Error(), "shipcheck local does not support --deliver") {
		t.Fatalf("error should explain --deliver is unsupported, got %v", err)
	}
	if _, statErr := os.Stat(target); !os.IsNotExist(statErr) {
		t.Fatalf("shipcheck local should reject --deliver before writing output, stat err=%v", statErr)
	}
	if _, statErr := os.Stat(filepath.Join(home, ".straddle-pp-cli")); !os.IsNotExist(statErr) {
		t.Fatalf("shipcheck local should reject --deliver before loading profile state, stat err=%v", statErr)
	}
}

func TestShipcheckLocalRejectsSecretLiteralMCPBinary(t *testing.T) {
	_, _, err := runCLIForDocsTest(t, "shipcheck", "local", "--mcp-binary", "straddle-pp-mcp --token sk_test_fixture", "--json")
	if err == nil {
		t.Fatalf("shipcheck local should reject token literals in --mcp-binary")
	}
	var cliErr *cliError
	if !errors.As(err, &cliErr) || cliErr.code != 2 {
		t.Fatalf("token literal rejection should be a usage error, got %#v", err)
	}
	if !strings.Contains(strings.ToLower(err.Error()), "token") {
		t.Fatalf("error should mention token literal rejection, got %v", err)
	}
}

func shipcheckCheckByName(t *testing.T, checks []shipcheckCheck, name string) shipcheckCheck {
	t.Helper()
	for _, check := range checks {
		if check.Name == name {
			return check
		}
	}
	t.Fatalf("missing check %q in %#v", name, checks)
	return shipcheckCheck{}
}
